namespace SpriteKind {
    export const GHOST = SpriteKind.create()
    export const METEORITE_1 = SpriteKind.create()
    export const METEORITE_2 = SpriteKind.create()
}
scene.onHitWall(SpriteKind.METEORITE_2, function (sprite, location) {
    if (tiles.tileAtLocationEquals(location, assets.tile`myTile5`)) {
        info.changeLifeBy(-1)
    }
    if (tiles.tileAtLocationEquals(location, assets.tile`myTile6`)) {
        info.changeLifeBy(-1)
        sprite.destroy()
        music.play(music.melodyPlayable(music.jumpDown), music.PlaybackMode.InBackground)
    }
})
sprites.onOverlap(SpriteKind.METEORITE_2, SpriteKind.Player, function (sprite, otherSprite) {
    FALL_SETTINGS = sprites.create(img`
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . c c c . . . . . . 
        . . . . . . a b a a . . . . . . 
        . . . . . c b a f c a c . . . . 
        . . . . c b b b f f a c c . . . 
        . . . . b b f a b b a a c . . . 
        . . . . c b f f b a f c a . . . 
        . . . . . c a a c b b a . . . . 
        . . . . . . c c c c . . . . . . 
        . . . . . . . c . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        `, SpriteKind.METEORITE_1)
    FALL_SETTINGS.setBounceOnWall(true)
    FALL_SETTINGS.setPosition(sprite.x, sprite.y - 5)
    FALL_SETTINGS.setVelocity(sprite.vx, 0 - sprite.vy)
    FALL_SETTINGS.ay = sprite.ay
    sprite.destroy()
    music.play(music.melodyPlayable(music.knock), music.PlaybackMode.InBackground)
})
