info.onLifeZero(function () {
    game.gameOver(false)
    music.play(music.melodyPlayable(music.wawawawaa), music.PlaybackMode.InBackground)
})
info.onScore(50, function () {
    game.gameOver(true)
    music.play(music.melodyPlayable(music.beamUp), music.PlaybackMode.LoopingInBackground)
})
sprites.onOverlap(SpriteKind.METEORITE_1, SpriteKind.Player, function (sprite, otherSprite) {
    info.setScore(info.score() + 1)
    sprite.destroy()
    music.play(music.melodyPlayable(music.baDing), music.PlaybackMode.InBackground)
})
scene.onHitWall(SpriteKind.METEORITE_1, function (sprite, location) {
    if (tiles.tileAtLocationEquals(location, assets.tile`myTile5`)) {
        info.changeLifeBy(-1)
        sprite.destroy()
        music.play(music.melodyPlayable(music.jumpDown), music.PlaybackMode.InBackground)
    }
    if (tiles.tileAtLocationEquals(location, assets.tile`myTile6`)) {
        info.changeLifeBy(-1)
        sprite.destroy()
        music.play(music.melodyPlayable(music.jumpDown), music.PlaybackMode.InBackground)
    }
})
